from google.cloud import firestore

def fetch_document(document_id, config=None):
    config = config or {}
    client = firestore.Client(project=config["project_id"])
    document_ref = client.collection(config["collection"]).document(document_id)
    document = document_ref.get()
    if document.exists:
        return document.to_dict()
    else:
        return None

from google.cloud import firestore

def conditional_update(document_id, update_payload, condition_payload, config=None):
    config = config or {}
    client = firestore.Client(project=config["project_id"])
    document_ref = client.collection(config["collection"]).document(document_id)
    document = document_ref.get()
    if document.exists and document.to_dict() == condition_payload:
        document_ref.update(update_payload)
        return {"id": document_id}
    else:
        return None

from google.cloud import firestore

def get_firestore_client(project_id):
    return firestore.Client(project=project_id)

def normalize_document(document):
    return {k: v for k, v in document.items() if not k.startswith('__')}

def summarize_document(document):
    summary = {k: v for k, v in document.items() if k in ['title', 'description']}
    return summary

import re

def check_text_safety(text):
    if re.search(r'[\W_]+', text):
        return False
    return True
